export class CsvParseError extends Error {}

export class CsvStreamParser {
  constructor() {
    this.buffer = '';
    this.columns = null;
  }

  write(chunk) {
    this.buffer += String(chunk);
    const rows = [];
    const lines = this.buffer.split('\n');
    this.buffer = lines.pop() ?? '';

    for (const line of lines) {
      const cleaned = line.endsWith('\r') ? line.slice(0, -1) : line;
      if (cleaned.length === 0) continue;
      rows.push(this.parseLine(cleaned));
    }

    return rows;
  }

  end() {
    if (this.buffer.length === 0) return [];
    const line = this.buffer;
    this.buffer = '';
    return [this.parseLine(line)];
  }

  parseLine(line) {
    const row = line.split(',');
    if (this.columns === null) {
      this.columns = row.length;
    } else if (row.length !== this.columns) {
      throw new CsvParseError(`ragged row: expected ${this.columns} columns, got ${row.length}`);
    }
    return row;
  }
}

export async function parseCsvStream(chunks) {
  const parser = new CsvStreamParser();
  const rows = [];
  for await (const chunk of chunks) {
    rows.push(...parser.write(chunk));
  }
  rows.push(...parser.end());
  return rows;
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { CsvParseError, CsvStreamParser, parseCsvStream } from '../src/csvStream.mjs';

test('emits complete unquoted rows incrementally', () => {
  const parser = new CsvStreamParser();
  assert.deepEqual(parser.write('name,age\nAda,'), [['name', 'age']]);
  assert.deepEqual(parser.write('37\nGrace,44'), [['Ada', '37']]);
  assert.deepEqual(parser.end(), [['Grace', '44']]);
});

test('parses quoted comma and escaped quote', async () => {
  assert.deepEqual(
    await parseCsvStream(['name,note\nAda,"ships, fast"\nGrace,"said ""hi"""\n']),
    [
      ['name', 'note'],
      ['Ada', 'ships, fast'],
      ['Grace', 'said "hi"'],
    ]
  );
});

test('rejects ragged rows with CsvParseError', async () => {
  await assert.rejects(
    parseCsvStream(['a,b\n1,2,3\n']),
    error => error instanceof CsvParseError && /ragged|column/i.test(error.message)
  );
});

export class CsvParseError extends Error {
  constructor(message) {
    super(message);
    this.name = 'CsvParseError';
  }
}

export class CsvStreamParser {
  constructor() {
    this.field = '';
    this.row = [];
    this.columns = null;
    this.inQuotes = false;
    this.afterQuote = false;
    this.fieldStarted = false;
    this.pendingCr = false;
  }

  write(chunk) {
    const rows = [];

    for (const char of String(chunk)) {
      if (this.pendingCr) {
        if (char === '\n') {
          this.pendingCr = false;
          continue;
        }
        this.pendingCr = false;
      }

      this.processChar(char, rows);
    }

    return rows;
  }

  end() {
    const rows = [];

    if (this.pendingCr) {
      this.pendingCr = false;
      this.finishRow(rows);
    }

    if (this.inQuotes) {
      throw new CsvParseError('malformed CSV: unterminated quoted field');
    }

    if (this.afterQuote) {
      this.afterQuote = false;
    }

    if (this.fieldStarted || this.field.length > 0 || this.row.length > 0) {
      this.finishRow(rows);
    }

    return rows;
  }

  processChar(char, rows) {
    if (this.inQuotes) {
      if (char === '"') {
        this.inQuotes = false;
        this.afterQuote = true;
      } else {
        this.field += char;
      }
      return;
    }

    if (this.afterQuote) {
      if (char === '"') {
        this.field += '"';
        this.inQuotes = true;
        this.afterQuote = false;
      } else if (char === ',') {
        this.finishField();
        this.afterQuote = false;
      } else if (char === '\n') {
        this.afterQuote = false;
        this.finishRow(rows);
      } else if (char === '\r') {
        this.afterQuote = false;
        this.finishRow(rows);
        this.pendingCr = true;
      } else {
        throw new CsvParseError('malformed CSV: unexpected character after closing quote');
      }
      return;
    }

    if (char === '"') {
      if (this.fieldStarted || this.field.length > 0) {
        throw new CsvParseError('malformed CSV: quote in unquoted field');
      }
      this.fieldStarted = true;
      this.inQuotes = true;
    } else if (char === ',') {
      this.finishField();
    } else if (char === '\n') {
      this.finishRow(rows);
    } else if (char === '\r') {
      this.finishRow(rows);
      this.pendingCr = true;
    } else {
      this.fieldStarted = true;
      this.field += char;
    }
  }

  finishField() {
    this.row.push(this.field);
    this.field = '';
    this.fieldStarted = false;
  }

  finishRow(rows) {
    this.finishField();
    const row = this.row;
    this.row = [];

    if (this.columns === null) {
      this.columns = row.length;
    } else if (row.length !== this.columns) {
      throw new CsvParseError(`ragged row: expected ${this.columns} columns, got ${row.length}`);
    }

    rows.push(row);
  }
}

export async function parseCsvStream(chunks) {
  const parser = new CsvStreamParser();
  const rows = [];
  for await (const chunk of chunks) {
    rows.push(...parser.write(chunk));
  }
  rows.push(...parser.end());
  return rows;
}

