import { test } from 'node:test';
import { CsvParseError, CsvStreamParser, parseCsvStream } from '../src/csvStream.mjs';

test('emits complete unquoted rows incrementally', () => {
  const parser = new CsvStreamParser();
  assert.deepEqual(parser.write('name,age\nAda,'), [['name', 'age']]);
  assert.deepEqual(parser.write('37\nGrace,44'), [['Ada', '37']]);
  assert.deepEqual(parser.end(), [['Grace', '44']]);
});

test('parses quoted comma and escaped quote', async () => {
  assert.deepEqual(
    await parseCsvStream(['name,note\nAda,"ships, fast"\nGrace,"said ""hi"""\n']),
    [
      ['name', 'note'],
      ['Ada', 'ships, fast'],
      ['Grace', 'said "hi"'],
    ]
  );
});

test('rejects ragged rows with CsvParseError', async () => {
  await assert.rejects(
    parseCsvStream(['a,b\n1,2,3\n']),
    error => error instanceof CsvParseError && /ragged|column/i.test(error.message)
  );
});

test('keeps quoted newlines while streaming across chunks', () => {
  const parser = new CsvStreamParser();
  assert.deepEqual(parser.write('id,note\r\n1,"hello'), [['id', 'note']]);
  assert.deepEqual(parser.write('\r\nworld"\r'), [['1', 'hello\r\nworld']]);
  assert.deepEqual(parser.write('\n2,"split ""quote"""'), []);
  assert.deepEqual(parser.end(), [['2', 'split "quote"']]);
});

test('handles CRLF split across chunk boundaries', async () => {
  assert.deepEqual(await parseCsvStream(['a,b\r', '\n1,2\r', '\n']), [
    ['a', 'b'],
    ['1', '2'],
  ]);
});

test('rejects malformed quoted fields with CsvParseError', async () => {
  await assert.rejects(
    parseCsvStream(['a,b\n1,"unterminated']),
    error => error instanceof CsvParseError && /unterminated/i.test(error.message)
  );

  await assert.rejects(
    parseCsvStream(['a,b\n1,"two"x\n']),
    error => error instanceof CsvParseError && /malformed|quote/i.test(error.message)
  );

  await assert.rejects(
    parseCsvStream(['a,b\n1,t"wo\n']),
    error => error instanceof CsvParseError && /malformed|quote/i.test(error.message)
  );
});

